        "voiceover": "快速生成一条商品广告。"
      }
    ],
    "tts": {
      "enabled": true,
      "source": "shots.voiceover",
      "voiceover": "快速生成一条商品广告。"
    },
    "assumptions": ["Postman smoke 使用固定 shotprompt，避免调用文本模型。"]
  }
